import{quantColour}from'./sprite-workbench.js';
const clamp=(n,a,b)=>Math.min(b,Math.max(a,Number(n)));
export function parseColour(value){let s=String(value).trim().replace(/^0x/i,'').replace(/^#/,'');if(/^[a-f\d]{3}$/i.test(s))s=[...s].map(c=>c+c).join('');if(!/^[a-f\d]{6}$/i.test(s))throw Error('Enter 3 or 6 hex digits, for example #8844CC.');return'#'+s.toLowerCase();}
export const colourRGB=hex=>[1,3,5].map(i=>parseInt(parseColour(hex).slice(i,i+2),16));
export function rgbHex(rgb){return'#'+rgb.map(n=>Math.round(clamp(n,0,255)).toString(16).padStart(2,'0')).join('');}
export function rgbHSV(rgb,previousHue=0){const[r,g,b]=rgb.map(n=>n/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min;let h=previousHue;if(d)h=(max===r?(g-b)/d+(g<b?6:0):max===g?(b-r)/d+2:(r-g)/d+4)*60;return[h,max?d/max*100:0,max*100];}
export function hsvRGB([h,s,v]){h=((h%360)+360)%360;s=clamp(s,0,100)/100;v=clamp(v,0,100)/100;const c=v*s,x=c*(1-Math.abs(h/60%2-1)),m=v-c,p=h<60?[c,x,0]:h<120?[x,c,0]:h<180?[0,c,x]:h<240?[0,x,c]:h<300?[x,0,c]:[c,0,x];return p.map(n=>Math.round((n+m)*255));}
/** Keep HSV intent independently: black/white must not erase the user's hue. */
export function colourDraft(hex,previousHue=0){let rgb=colourRGB(hex),hsv=rgbHSV(rgb,previousHue);return{get hex(){return rgbHex(rgb);},get rgb(){return[...rgb];},get hsv(){return[...hsv];},setHex(value){rgb=colourRGB(value);hsv=rgbHSV(rgb,hsv[0]);},setRGB(i,value){rgb[i]=clamp(value,0,255);hsv=rgbHSV(rgb,hsv[0]);},setHSV(i,value){hsv[i]=clamp(value,0,i===0?360:100);rgb=hsvRGB(hsv);}};}
export function mountColourPicker(api){
 const root=api.root,$=s=>root.querySelector(s);let model,key,base,busy=false,sampling=null;
 root.innerHTML=`<div class="colour-heading"><button id="spriteColour" type="button" class="colour-current" aria-label="Edit selected swatch"><span id="colourCurrentChip"></span><span id="colourCurrentLabel">Selected colour</span></button><button id="spritePaletteTools" type="button">Saved palettes</button></div><div class="colour-hex-row"><label>Hex colour<input id="spriteHex" type="text" maxlength="32" placeholder="#8844CC" autocomplete="off" autocapitalize="off" spellcheck="false" enterkeyhint="done"></label><button id="spriteApplyHex" type="button" class="primary">Apply colour</button></div><p id="colourMessage" class="colour-message" role="status" aria-live="polite"></p><div class="colour-preview-row"><span>Current <i id="colourOld"></i></span><span>New <i id="colourNew"></i></span><span id="colourGBACode"></span></div><details id="colourAdjust" open><summary>Adjust colour</summary><div class="colour-mode" role="group" aria-label="Colour controls"><button data-colour-mode="hsv" type="button" class="active">Hue / tint / brightness</button><button data-colour-mode="rgb" type="button">Red / green / blue</button></div><div id="colourHSV">${[['Hue',360],['Tint %',100],['Brightness %',100]].map(([n,max],i)=>`<label class="colour-channel"><span>${n}</span><input id="colourHSV${i}" type="range" min="0" max="${max}" step="${i?'.1':'1'}" aria-label="${n}"><input id="colourHSVNumber${i}" type="number" min="0" max="${max}" step="${i?'.1':'1'}" aria-label="${n} value"></label>`).join('')}</div><div id="colourRGB" hidden>${['Red','Green','Blue'].map((n,i)=>`<label class="colour-channel"><span>${n}</span><input id="colourRGB${i}" type="range" min="0" max="255" step="1" aria-label="${n}"><input id="colourRGBNumber${i}" type="number" min="0" max="255" step="1" aria-label="${n} value"></label>`).join('')}</div><div class="colour-nudge"><button data-colour-nudge="lighter" type="button">Lighter</button><button data-colour-nudge="darker" type="button">Darker</button><button data-colour-nudge="less" type="button">Less tint</button><button data-colour-nudge="more" type="button">More tint</button><button id="colourReset" type="button">Reset preview</button></div><p class="hint-line">Adjustments preview here. Apply changes the selected swatch and every pixel using it. The GBA stores the nearest 15-bit colour.</p></details><div id="colourSharing" class="colour-sharing" hidden><b>Shared native palette</b><p id="colourSharingText"></p><label class="check"><input id="spriteSharedPalette" type="checkbox"> Apply to all sprites sharing this native palette</label><button id="colourIndependent" type="button">Make an independent copy & apply</button></div><div class="colour-source-actions"><button id="colourSampleImage" type="button">Sample a picture</button><button id="colourSampleReference" type="button">Use tracing picture</button><button id="colourPickSprite" type="button">Pick a sprite colour</button></div><input id="colourSourceFile" type="file" accept="image/png,image/jpeg,image/webp" hidden><div id="colourSource" hidden><p>Tap a pixel to sample its colour, then Apply colour.</p><div class="colour-source-scroll"><canvas id="colourSourceCanvas" aria-label="Tap picture to sample a colour"></canvas></div><p id="colourSampleValue"></p><button id="colourCloseSource" type="button">Close picture</button></div>`;
 const message=(text,error=false)=>{$('#colourMessage').textContent=text;$('#colourMessage').classList.toggle('error-text',error);};
 const preview=(keepHex=false)=>{
  const hex=model.hex,rgb=model.rgb,hsv=model.hsv;
  $('#colourOld').style.background=base;$('#colourNew').style.background=hex;$('#colourCurrentChip').style.background=base;$('#colourCurrentLabel').textContent='Swatch '+api.index()+' · '+base.toUpperCase();$('#colourGBACode').textContent='GBA: '+quantColour(hex).toUpperCase();
  if(!keepHex&&document.activeElement!==$('#spriteHex'))$('#spriteHex').value=hex;
  for(let i=0;i<3;i++)for(const[type,values]of[['HSV',hsv],['RGB',rgb]]){const n=values[i];$('#colour'+type+i).value=n;const field=$('#colour'+type+'Number'+i);if(document.activeElement!==field)field.value=Math.round(n*10)/10;}
  $('#colourHSV0').style.background='linear-gradient(to right,#f00,#ff0,#0f0,#0ff,#00f,#f0f,#f00)';const hue=rgbHex(hsvRGB([hsv[0],100,100]));$('#colourHSV1').style.background='linear-gradient(to right,#fff,'+hue+')';$('#colourHSV2').style.background='linear-gradient(to right,#000,'+rgbHex(hsvRGB([hsv[0],hsv[1],100]))+')';
  for(let i=0;i<3;i++){const low=[...rgb],high=[...rgb];low[i]=0;high[i]=255;$('#colourRGB'+i).style.background='linear-gradient(to right,'+rgbHex(low)+','+rgbHex(high)+')';}
 };
 function sync(){const next=api.key(),colour=api.colour();if(next!==key||colour!==base){const hue=model?.hsv[0]||0;key=next;base=colour;model=colourDraft(colour,hue);$('#spriteHex').value=model.hex;message('');preview();}const count=api.sharedCount();$('#colourSharing').hidden=count<2;$('#colourSharingText').textContent='This palette is used by '+count+' native sprites. To change only this group, make a copy. To edit them together, enable the switch.';$('#spriteSharedPalette').checked=api.shared();$('#colourSampleReference').disabled=!api.reference();const transparent=api.index()===0;$('#spriteApplyHex').disabled=transparent;$('#colourIndependent').disabled=transparent||busy;if(transparent)message('Swatch 0 is transparent. Choose one of the other 15 colours to edit.');}
 function readHex(){try{model.setHex($('#spriteHex').value);preview(true);return true;}catch(e){message(e.message,true);return false;}}
 async function apply(copy=false){if(busy)return false;if(api.index()===0)return true;if(!readHex())return false;if(!copy&&quantColour(model.hex)===api.colour()){preview();return true;}if(!copy&&api.sharedCount()>1&&!api.shared()){message('Choose “Make an independent copy & apply”, or enable shared-palette editing below.',true);$('#colourSharing').hidden=false;return false;}const wanted=model.hex;try{busy=true;$('#spriteApplyHex').disabled=true;$('#colourIndependent').disabled=true;if(copy)await api.copy(wanted);else api.apply(wanted);if(!copy){base=api.colour();model=colourDraft(base,model.hsv[0]);$('#spriteHex').value=base;preview();message('Swatch updated to '+base.toUpperCase()+'.');}return true;}catch(e){message(e.message,true);return false;}finally{busy=false;if(root.isConnected)sync();}}
 $('#spriteHex').oninput=()=>{try{model.setHex($('#spriteHex').value);preview(true);message('Preview ready. Tap Apply colour.');}catch{message('Finish the hex code, then tap Apply colour.');}};
 $('#spriteHex').onchange=readHex;$('#spriteHex').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();e.stopPropagation();apply();}};
 $('#spriteApplyHex').onclick=()=>apply();$('#colourIndependent').onclick=()=>apply(true);$('#spriteSharedPalette').onchange=()=>{api.setShared($('#spriteSharedPalette').checked);message($('#spriteSharedPalette').checked?'Shared editing enabled. Tap Apply colour to commit.':'Changes can be applied to an independent copy.');};
 $('#spriteColour').onclick=()=>{$('#colourAdjust').open=!$('#colourAdjust').open;};$('#colourReset').onclick=()=>{model=colourDraft(base,model.hsv[0]);$('#spriteHex').value=model.hex;preview();message('Preview reset to the selected swatch.');};
 root.querySelectorAll('[data-colour-mode]').forEach(b=>b.onclick=()=>{const rgb=b.dataset.colourMode==='rgb';$('#colourRGB').hidden=!rgb;$('#colourHSV').hidden=rgb;root.querySelectorAll('[data-colour-mode]').forEach(x=>x.classList.toggle('active',x===b));});
 for(let i=0;i<3;i++)for(const type of['RGB','HSV'])for(const suffix of['','Number']){const input=$('#colour'+type+suffix+i);input.oninput=()=>{if(input.value===''||!Number.isFinite(+input.value))return;type==='RGB'?model.setRGB(i,+input.value):model.setHSV(i,+input.value);$('#spriteHex').value=model.hex;preview();message('Preview ready. Tap Apply colour.');};input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();apply();}};}
 root.querySelectorAll('[data-colour-nudge]').forEach(b=>b.onclick=()=>{const id=b.dataset.colourNudge,hsv=model.hsv;model.setHSV(['lighter','darker'].includes(id)?2:1,['lighter','darker'].includes(id)?hsv[2]+(id==='lighter'?3.3:-3.3):hsv[1]+(id==='more'?3.3:-3.3));$('#spriteHex').value=model.hex;preview();message('Preview ready. Tap Apply colour.');});
 async function sampleFile(file){if(file.size>10*1024*1024)throw Error('Choose a picture under 10 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('The picture could not be read.'));r.readAsDataURL(file);});const image=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Choose a PNG, JPG or WebP picture.'));im.src=data;});showSource(image);}
 function showSource(image){if(!image||image.width*image.height>16e6)throw Error('Use a picture under 16 megapixels.');sampling=image;const c=$('#colourSourceCanvas'),scale=Math.min(1,640/image.width,480/image.height);c.width=Math.max(1,Math.round(image.width*scale));c.height=Math.max(1,Math.round(image.height*scale));const ctx=c.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(image,0,0,c.width,c.height);$('#colourSource').hidden=false;$('#colourSampleValue').textContent='';}
 function sampleAt(e){if(!sampling)return;const c=$('#colourSourceCanvas'),rect=c.getBoundingClientRect(),x=clamp(Math.floor((e.clientX-rect.left)/rect.width*sampling.width),0,sampling.width-1),y=clamp(Math.floor((e.clientY-rect.top)/rect.height*sampling.height),0,sampling.height-1),pixel=document.createElement('canvas');pixel.width=pixel.height=1;const ctx=pixel.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(sampling,x,y,1,1,0,0,1,1);const p=ctx.getImageData(0,0,1,1).data;if(p[3]<128){message('That pixel is transparent. Choose an opaque pixel.',true);return;}model.setHex(rgbHex([...p].slice(0,3)));$('#spriteHex').value=model.hex;preview();$('#colourSampleValue').textContent=model.hex.toUpperCase()+' · pixel '+x+', '+y;message('Colour sampled. Tap Apply colour.');}
 $('#colourSampleImage').onclick=()=>$('#colourSourceFile').click();$('#colourSourceFile').onchange=async e=>{try{const f=e.target.files?.[0];if(f)await sampleFile(f);}catch(e){message(e.message,true);}e.target.value='';};$('#colourSampleReference').onclick=async()=>{try{showSource(await api.referenceImage());}catch(e){message(e.message,true);}};$('#colourSourceCanvas').addEventListener('click',sampleAt);$('#colourCloseSource').onclick=()=>{$('#colourSource').hidden=true;sampling=null;};$('#colourPickSprite').onclick=api.pickSprite;$('#spritePaletteTools').onclick=api.palettes;
 sync();return{sync,apply,sampleFile,showSource,get draft(){return model;}};
}
